62	function fmtDate(d: string | null) {
63	  if (!d) return "—";
64	  try {
65	    return format(parseISO(d), "MMM d, yyyy");
66	  } catch {
67	    return "—";
68	  }
69	}
70	
71	function fmtCurrency(amount: number | null, currency = "USD") {
72	  if (amount == null) return "—";
73	  return new Intl.NumberFormat("en-US", {
74	    style: "currency",
75	    currency,
76	    maximumFractionDigits: 0,
77	  }).format(amount);
78	}
