80	function GuarantyBadge({ expiresAt }: { expiresAt: string | null }) {
81	  if (!expiresAt) return <span className="text-muted-foreground text-xs">—</span>;
82	  const days = differenceInDays(parseISO(expiresAt), new Date());
83	  if (days < 0) return <Badge variant="destructive" className="text-[10px]">Expired</Badge>;
84	  if (days <= 7) return <Badge variant="destructive" className="text-[10px]">{days}d left</Badge>;
85	  return <Badge variant="secondary" className="text-[10px]">{days}d left</Badge>;
86	}
