88	function StatusBadge({ status }: { status: string }) {
89	  const map: Record<string, string> = {
90	    active: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
91	    inactive: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
92	    churned: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
93	    open: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
94	    in_progress: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
95	    filled: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
96	    cancelled: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
97	    offered: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
98	    accepted: "bg-violet-100 text-violet-800 dark:bg-violet-900/30 dark:text-violet-400",
99	    started: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
100	    guarantee: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
101	    completed: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
102	    fallen_off: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
103	    draft: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
104	    sent: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
105	    paid: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
106	    overdue: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
107	    pending: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
108	    approved: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
109	    high: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
110	    medium: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
111	    low: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
112	  };
113	  const cls = map[status] ?? "bg-gray-100 text-gray-600";
114	  const label = status.replace(/_/g, " ");
115	  return (
116	    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium capitalize ${cls}`}>
117	      {label}
118	    </span>
119	  );
