26	// ─── Hook ─────────────────────────────────────────────────────────────────────
27	
28	export function useAgencyMandates(teamId: string | null) {
29	  const queryClient = useQueryClient();
30	  const queryKey = ["agency_mandates", teamId];
31	
32	  const { data, isLoading, error } = useQuery({
33	    queryKey,
34	    queryFn: async (): Promise<AgencyMandate[]> => {
35	      if (!teamId) return [];
36	      try {
37	        const { data, error } = await (supabase as any)
38	          .from("agency_mandates")
39	          .select("*, agency_clients(company_name)")
40	          .eq("team_id", teamId)
41	          .order("created_at", { ascending: false });
42	        if (error) throw error;
43	
44	        return ((data ?? []) as any[]).map((row) => ({
45	          ...row,
46	          client_name: row.agency_clients?.company_name ?? null,
47	          agency_clients: undefined,
48	        })) as AgencyMandate[];
49	      } catch {
50	        return [];
51	      }
52	    },
53	    enabled: !!teamId,
54	    staleTime: 30_000,
55	  });
56	
