import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

// ─── Types ────────────────────────────────────────────────────────────────────

export type CommType = "call" | "email" | "meeting" | "note";

export interface AgencyCommunication {
  id: string;
  client_id: string;
  team_id: string;
  type: CommType;
  subject: string;
  body: string | null;
  occurred_at: string;
  created_by: string | null;
  created_at: string;
}

export type CreateCommInput = {
  client_id: string;
  team_id: string;
  type: CommType;
  subject: string;
  body?: string | null;
  occurred_at: string;
  created_by?: string | null;
};

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function useAgencyCommunications(teamId: string | null, clientId?: string | null) {
  const queryClient = useQueryClient();
  const queryKey = ["agency_communications", teamId, clientId ?? "all"];

  const { data, isLoading, error } = useQuery({
    queryKey,
    queryFn: async (): Promise<AgencyCommunication[]> => {
      if (!teamId) return [];
      try {
        let q = (supabase as any)
          .from("agency_communications")
          .select("*")
          .eq("team_id", teamId)
          .order("occurred_at", { ascending: false });

        if (clientId) {
          q = q.eq("client_id", clientId);
        }

        const { data, error } = await q;
        if (error) throw error;
        return (data ?? []) as AgencyCommunication[];
      } catch {
        return [];
      }
    },
    enabled: !!teamId,
    staleTime: 30_000,
  });

  const createComm = useMutation({
    mutationFn: async (input: Omit<CreateCommInput, "team_id">) => {
      if (!teamId) throw new Error("No team");
      const { data, error } = await (supabase as any)
        .from("agency_communications")
        .insert({ ...input, team_id: teamId })
        .select()
        .single();
      if (error) throw error;
      return data as AgencyCommunication;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["agency_communications", teamId] });
      toast.success("Log entry added");
    },
    onError: (err: Error) => {
      toast.error(`Failed to log: ${err.message}`);
    },
  });

  const deleteComm = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await (supabase as any)
        .from("agency_communications")
        .delete()
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["agency_communications", teamId] });
      toast.success("Entry removed");
    },
    onError: (err: Error) => {
      toast.error(`Failed to remove: ${err.message}`);
    },
  });

  return {
    communications: data ?? [],
    isLoading,
    error,
    createComm,
    deleteComm,
  };
}

import { useState, useMemo } from "react";
import { format, differenceInDays, parseISO, addDays, isAfter } from "date-fns";
import {
  Users,
