  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Progress } from "@/components/ui/progress";
import { useAuth } from "@/hooks/useAuth";
import { useTeam } from "@/hooks/useTeam";
import { useAgencyClients, type AgencyClient } from "@/hooks/useAgencyClients";
import { useAgencyMandates, type AgencyMandate } from "@/hooks/useAgencyMandates";
import { useAgencyPlacements, type AgencyPlacement } from "@/hooks/useAgencyPlacements";
import { useAgencyInvoices, type AgencyInvoice } from "@/hooks/useAgencyInvoices";
import { useAgencyCommissions } from "@/hooks/useAgencyCommissions";
import {
  useAgencyCommunications,
  type AgencyCommunication,
  type CommType,
} from "@/hooks/useAgencyCommunications";
import { toast } from "sonner";

// ─── Helpers ──────────────────────────────────────────────────────────────────

function fmtDate(d: string | null) {
  if (!d) return "—";
  try {
    return format(parseISO(d), "MMM d, yyyy");
  } catch {
    return "—";
  }
}

function fmtDateTime(d: string | null) {
  if (!d) return "—";
  try {
    return format(parseISO(d), "MMM d, yyyy · h:mm a");
  } catch {
    return "—";
  }
}

function fmtCurrency(amount: number | null, currency = "USD") {
  if (amount == null) return "—";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(amount);
}

// ─── DeadlineBadge ────────────────────────────────────────────────────────────

function DeadlineBadge({ deadline }: { deadline: string | null }) {
  if (!deadline) return <span className="text-muted-foreground text-xs">—</span>;
  try {
    const days = differenceInDays(parseISO(deadline), new Date());
    if (days < 0) {
      return (
        <span className="inline-flex items-center gap-1 text-[11px] font-medium text-red-600 dark:text-red-400">
          <AlertTriangle className="h-3 w-3" />
          {Math.abs(days)}d overdue
        </span>
      );
    }
    if (days === 0) {
      return <Badge variant="destructive" className="text-[10px]">Due today</Badge>;
    }
    if (days <= 3) {
      return <Badge variant="destructive" className="text-[10px]">{days}d left</Badge>;
    }
    if (days <= 7) {
      return (
        <span className="inline-flex items-center gap-1 text-[11px] font-medium text-amber-600 dark:text-amber-400">
          <Clock className="h-3 w-3" />
          {days}d left
        </span>
      );
    }
    return <span className="text-[11px] text-muted-foreground">{fmtDate(deadline)}</span>;
  } catch {
    return <span className="text-muted-foreground text-xs">—</span>;
  }
}

// ─── GuarantyProgress ─────────────────────────────────────────────────────────

function GuarantyProgress({
  startDate,
  guaranteeDays,
  expiresAt,
}: {
  startDate: string | null;
  guaranteeDays: number | null;
  expiresAt: string | null;
}) {
  if (!startDate || !guaranteeDays || !expiresAt) {
    return <span className="text-muted-foreground text-xs">—</span>;
  }
  try {
    const start = parseISO(startDate);
    const end = parseISO(expiresAt);
    const total = differenceInDays(end, start);
    const elapsed = differenceInDays(new Date(), start);
    const daysLeft = differenceInDays(end, new Date());

    if (daysLeft < 0) {
      return <Badge variant="destructive" className="text-[10px]">Expired</Badge>;
    }

    const pct = Math.min(100, Math.max(0, (elapsed / total) * 100));
    const color = pct > 85 ? "bg-red-500" : pct > 60 ? "bg-amber-500" : "bg-emerald-500";

    return (
      <div className="space-y-1 min-w-[100px]">
        <div className="flex items-center justify-between gap-2">
          <span className="text-[10px] text-muted-foreground">{daysLeft}d left</span>
          <span className="text-[10px] text-muted-foreground">{Math.round(pct)}%</span>
        </div>
        <div className="h-1.5 w-full rounded-full bg-muted overflow-hidden">
          <div className={`h-full rounded-full transition-all ${color}`} style={{ width: `${pct}%` }} />
        </div>
      </div>
    );
  } catch {
    return <span className="text-muted-foreground text-xs">—</span>;
  }
}

// ─── StatusBadge ─────────────────────────────────────────────────────────────

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, string> = {
    active: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    inactive: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
    churned: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
    open: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
    in_progress: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
    filled: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    cancelled: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
    offered: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
    accepted: "bg-violet-100 text-violet-800 dark:bg-violet-900/30 dark:text-violet-400",
    started: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    guarantee: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
    completed: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    fallen_off: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
    draft: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
    sent: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
    paid: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    overdue: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
    pending: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
    approved: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
    high: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
    medium: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
    low: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
  };
  const cls = map[status] ?? "bg-gray-100 text-gray-600";
  const label = status.replace(/_/g, " ");
  return (
    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium capitalize ${cls}`}>
      {label}
    </span>
  );
}

function TableSkeleton({ cols = 5, rows = 4 }: { cols?: number; rows?: number }) {
  return (
    <>
      {Array.from({ length: rows }).map((_, i) => (
        <TableRow key={i}>
          {Array.from({ length: cols }).map((_, j) => (
            <TableCell key={j}>
              <Skeleton className="h-4 w-full" />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}

function EmptyRow({ cols, message }: { cols: number; message: string }) {
  return (
    <TableRow>
      <TableCell colSpan={cols} className="py-12 text-center">
        <div className="flex flex-col items-center gap-2 text-muted-foreground">
          <Building2 className="h-8 w-8 opacity-30" />
          <span className="text-sm">{message}</span>
        </div>
      </TableCell>
    </TableRow>
  );
}

function SummaryCard({
  label,
  value,
  icon: Icon,
  sub,
  accent,
}: {
  label: string;
  value: string;
  icon: React.ElementType;
  sub?: string;
  accent?: "red" | "amber" | "emerald";
}) {
  const accentCls =
    accent === "red"
      ? "text-red-600 dark:text-red-400"
      : accent === "amber"
      ? "text-amber-600 dark:text-amber-400"
      : accent === "emerald"
      ? "text-emerald-600 dark:text-emerald-400"
      : "text-foreground";

  return (
    <Card className="border border-border/60 shadow-sm">
      <CardContent className="p-5">
        <div className="flex items-start justify-between">
          <div className="space-y-1">
            <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">{label}</p>
            <p className={`text-2xl font-bold ${accentCls}`}>{value}</p>
            {sub && <p className="text-xs text-muted-foreground">{sub}</p>}
          </div>
          <div className="rounded-lg bg-muted/50 p-2">
            <Icon className={`h-5 w-5 ${accent ? accentCls : "text-muted-foreground"}`} />
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

// ─── Comm Type Icon ───────────────────────────────────────────────────────────

function CommTypeIcon({ type }: { type: CommType }) {
  const map: Record<CommType, { icon: React.ElementType; color: string }> = {
    call: { icon: Phone, color: "text-emerald-600 dark:text-emerald-400" },
    email: { icon: Mail, color: "text-blue-600 dark:text-blue-400" },
    meeting: { icon: Calendar, color: "text-violet-600 dark:text-violet-400" },
    note: { icon: StickyNote, color: "text-amber-600 dark:text-amber-400" },
  };
  const { icon: Icon, color } = map[type] ?? { icon: StickyNote, color: "text-muted-foreground" };
  return <Icon className={`h-4 w-4 shrink-0 ${color}`} />;
}

// ─── Communication Log Panel ──────────────────────────────────────────────────

function CommLogPanel({
  clientId,
  clientName,
  teamId,
  userId,
  onClose,
}: {
  clientId: string;
  clientName: string;
  teamId: string;
  userId: string;
  onClose: () => void;
}) {
  const { communications, isLoading, createComm, deleteComm } = useAgencyCommunications(teamId, clientId);

  const [addOpen, setAddOpen] = useState(false);
  const [form, setForm] = useState<{
    type: CommType;
    subject: string;
    body: string;
    occurred_at: string;
  }>({
    type: "call",
    subject: "",
    body: "",
    occurred_at: format(new Date(), "yyyy-MM-dd'T'HH:mm"),
  });

  function resetForm() {
    setForm({ type: "call", subject: "", body: "", occurred_at: format(new Date(), "yyyy-MM-dd'T'HH:mm") });
  }

  async function handleAddComm() {
    if (!form.subject.trim()) {
      toast.error("Subject is required");
      return;
    }
    await createComm.mutateAsync({
      client_id: clientId,
      type: form.type,
      subject: form.subject.trim(),
      body: form.body.trim() || null,
      occurred_at: new Date(form.occurred_at).toISOString(),
      created_by: userId,
    });
    setAddOpen(false);
    resetForm();
  }

  return (
    <Dialog open onOpenChange={(o) => { if (!o) onClose(); }}>
      <DialogContent className="sm:max-w-[580px] max-h-[85vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <MessageSquare className="h-4 w-4 text-muted-foreground" />
            Communication Log — {clientName}
          </DialogTitle>
        </DialogHeader>

        <div className="flex justify-end">
          <Button size="sm" className="gap-1.5" onClick={() => { resetForm(); setAddOpen(true); }}>
            <Plus className="h-3.5 w-3.5" />
            Log Entry
          </Button>
        </div>

        <div className="flex-1 overflow-y-auto space-y-2 pr-1">
          {isLoading ? (
            <div className="space-y-2">
              {[1, 2, 3].map((i) => (
                <div key={i} className="flex gap-3 p-3 rounded-lg border border-border/50">
                  <Skeleton className="h-4 w-4 mt-0.5 shrink-0 rounded" />
                  <div className="flex-1 space-y-1.5">
                    <Skeleton className="h-3.5 w-2/3" />
                    <Skeleton className="h-3 w-1/2" />
                  </div>
                </div>
              ))}
            </div>
          ) : communications.length === 0 ? (
            <div className="py-10 flex flex-col items-center gap-2 text-muted-foreground">
              <MessageSquare className="h-8 w-8 opacity-30" />
              <p className="text-sm">No communications logged yet.</p>
            </div>
          ) : (
            communications.map((c) => (
              <div
                key={c.id}
                className="flex gap-3 p-3 rounded-lg border border-border/50 hover:bg-muted/20 transition-colors group"
              >
                <div className="mt-0.5">
                  <CommTypeIcon type={c.type} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium leading-snug">{c.subject}</p>
                  {c.body && (
                    <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{c.body}</p>
                  )}
                  <p className="text-[10px] text-muted-foreground mt-1">{fmtDateTime(c.occurred_at)}</p>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-6 w-6 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity text-destructive hover:text-destructive"
                  onClick={() => {
                    if (confirm("Remove this entry?")) {
                      deleteComm.mutate(c.id);
                    }
                  }}
                >
                  <Trash2 className="h-3 w-3" />
                </Button>
              </div>
            ))
          )}
        </div>

        {/* Add Entry Dialog (nested) */}
        <Dialog open={addOpen} onOpenChange={setAddOpen}>
          <DialogContent className="sm:max-w-[440px]">
            <DialogHeader>
              <DialogTitle>Log Communication</DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label>Type</Label>
                  <Select value={form.type} onValueChange={(v) => setForm((f) => ({ ...f, type: v as CommType }))}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="call">Call</SelectItem>
                      <SelectItem value="email">Email</SelectItem>
                      <SelectItem value="meeting">Meeting</SelectItem>
                      <SelectItem value="note">Note</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-1.5">
                  <Label>Date & Time</Label>
                  <Input
                    type="datetime-local"
                    value={form.occurred_at}
                    onChange={(e) => setForm((f) => ({ ...f, occurred_at: e.target.value }))}
                  />
                </div>
              </div>
              <div className="space-y-1.5">
                <Label>Subject *</Label>
                <Input
                  value={form.subject}
                  onChange={(e) => setForm((f) => ({ ...f, subject: e.target.value }))}
                  placeholder="Discovery call, Follow-up email..."
                />
              </div>
              <div className="space-y-1.5">
                <Label>Notes</Label>
                <Textarea
                  value={form.body}
                  onChange={(e) => setForm((f) => ({ ...f, body: e.target.value }))}
                  placeholder="Key points discussed, next steps..."
                  rows={3}
                />
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setAddOpen(false)}>Cancel</Button>
              <Button onClick={handleAddComm} disabled={createComm.isPending}>
                {createComm.isPending ? "Saving..." : "Log Entry"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </DialogContent>
    </Dialog>
  );
}

// ─── Clients Tab ──────────────────────────────────────────────────────────────

function ClientsTab({ teamId }: { teamId: string }) {
  const { user } = useAuth();
  const { clients, isLoading, createClient, updateClient, deleteClient } = useAgencyClients(teamId);
  const { mandates } = useAgencyMandates(teamId);
  const { placements } = useAgencyPlacements(teamId);

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [addOpen, setAddOpen] = useState(false);
  const [editClient, setEditClient] = useState<AgencyClient | null>(null);
  const [commClientId, setCommClientId] = useState<string | null>(null);

  const [form, setForm] = useState({
    company_name: "",
    industry: "",
    website: "",
    sla_days: "",
    notes: "",
    status: "active" as AgencyClient["status"],
  });

  function resetForm() {
    setForm({ company_name: "", industry: "", website: "", sla_days: "", notes: "", status: "active" });
  }

  function openEdit(c: AgencyClient) {
    setEditClient(c);
    setForm({
      company_name: c.company_name,
      industry: c.industry ?? "",
      website: c.website ?? "",
      sla_days: c.sla_days?.toString() ?? "",
      notes: c.notes ?? "",
      status: c.status,
    });
  }

  async function handleSubmit() {
    if (!form.company_name.trim()) {
      toast.error("Company name is required");
      return;
    }
    const payload = {
      company_name: form.company_name.trim(),
      industry: form.industry.trim() || null,
      website: form.website.trim() || null,
      logo_url: null,
      sla_days: form.sla_days ? parseInt(form.sla_days) : null,
      notes: form.notes.trim() || null,
      status: form.status,
    };
    if (editClient) {
      await updateClient.mutateAsync({ id: editClient.id, ...payload });
      setEditClient(null);
    } else {
      await createClient.mutateAsync(payload);
      setAddOpen(false);
    }
    resetForm();
  }

  const filtered = useMemo(() => {
    return clients.filter((c) => {
      const matchSearch =
        !search ||
        c.company_name.toLowerCase().includes(search.toLowerCase()) ||
        (c.industry ?? "").toLowerCase().includes(search.toLowerCase());
      const matchStatus = statusFilter === "all" || c.status === statusFilter;
      return matchSearch && matchStatus;
    });
  }, [clients, search, statusFilter]);

  const activeCount = clients.filter((c) => c.status === "active").length;
  const mandateCountFor = (clientId: string) =>
    mandates.filter((m) => m.client_id === clientId && m.status !== "cancelled").length;
  const placementCountFor = (clientId: string) =>
    placements.filter((p) => p.client_id === clientId).length;

  const commClient = clients.find((c) => c.id === commClientId) ?? null;

  const FormFields = (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
      <div className="sm:col-span-2 space-y-1.5">
        <Label>Company Name *</Label>
        <Input
          value={form.company_name}
          onChange={(e) => setForm((f) => ({ ...f, company_name: e.target.value }))}
          placeholder="Acme Recruiting Ltd"
        />
      </div>
      <div className="space-y-1.5">
        <Label>Industry</Label>
        <Input
          value={form.industry}
          onChange={(e) => setForm((f) => ({ ...f, industry: e.target.value }))}
          placeholder="Technology, Finance..."
        />
      </div>
      <div className="space-y-1.5">
        <Label>Website</Label>
        <Input
          value={form.website}
          onChange={(e) => setForm((f) => ({ ...f, website: e.target.value }))}
          placeholder="https://acme.com"
        />
      </div>
      <div className="space-y-1.5">
        <Label>SLA Days</Label>
        <Input
          type="number"
          value={form.sla_days}
          onChange={(e) => setForm((f) => ({ ...f, sla_days: e.target.value }))}
          placeholder="30"
          min={1}
        />
      </div>
      <div className="space-y-1.5">
        <Label>Status</Label>
        <Select
          value={form.status}
          onValueChange={(v) => setForm((f) => ({ ...f, status: v as AgencyClient["status"] }))}
        >
          <SelectTrigger>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="active">Active</SelectItem>
            <SelectItem value="inactive">Inactive</SelectItem>
            <SelectItem value="churned">Churned</SelectItem>
          </SelectContent>
        </Select>
      </div>
      <div className="sm:col-span-2 space-y-1.5">
        <Label>Notes</Label>
        <Textarea
          value={form.notes}
          onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))}
          placeholder="Key contacts, preferences, history..."
          rows={3}
        />
      </div>
    </div>
  );

  const isSaving = createClient.isPending || updateClient.isPending;

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
        <SummaryCard label="Active Clients" value={String(activeCount)} icon={Users} accent="emerald" />
        <SummaryCard label="Total Mandates" value={String(mandates.length)} icon={FileText} />
        <SummaryCard label="Total Placements" value={String(placements.length)} icon={Award} />
      </div>

      <div className="flex flex-col sm:flex-row gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search clients..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-full sm:w-[140px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Statuses</SelectItem>
            <SelectItem value="active">Active</SelectItem>
            <SelectItem value="inactive">Inactive</SelectItem>
            <SelectItem value="churned">Churned</SelectItem>
          </SelectContent>
        </Select>
        <Button onClick={() => { resetForm(); setAddOpen(true); }} className="shrink-0 gap-1.5">
          <Plus className="h-4 w-4" />
          Add Client
        </Button>
      </div>

      <Card className="border border-border/60 shadow-sm">
        <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead>Company</TableHead>
              <TableHead>Industry</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>SLA</TableHead>
              <TableHead>Mandates</TableHead>
              <TableHead>Placements</TableHead>
              <TableHead>Added</TableHead>
              <TableHead className="w-[100px]"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton cols={8} />
            ) : filtered.length === 0 ? (
              <EmptyRow cols={8} message={clients.length === 0 ? "No clients yet. Add your first client." : "No clients match your filter."} />
            ) : (
              filtered.map((c) => (
                <TableRow key={c.id} className="hover:bg-muted/30 transition-colors">
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-muted text-xs font-semibold">
                        {c.company_name.charAt(0).toUpperCase()}
                      </div>
                      <span className="font-medium text-sm">{c.company_name}</span>
                    </div>
                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">{c.industry ?? "—"}</TableCell>
                  <TableCell><StatusBadge status={c.status} /></TableCell>
                  <TableCell className="text-sm">{c.sla_days ? `${c.sla_days}d` : "—"}</TableCell>
                  <TableCell className="text-sm">{mandateCountFor(c.id)}</TableCell>
                  <TableCell className="text-sm">{placementCountFor(c.id)}</TableCell>
                  <TableCell className="text-sm text-muted-foreground">{fmtDate(c.created_at)}</TableCell>
                  <TableCell>
                    <div className="flex items-center gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7"
                        title="Communication log"
                        onClick={() => setCommClientId(c.id)}
                      >
                        <MessageSquare className="h-3.5 w-3.5" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7"
                        onClick={() => openEdit(c)}
                      >
                        <Pencil className="h-3.5 w-3.5" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 text-destructive hover:text-destructive"
                        onClick={() => {
                          if (confirm(`Delete ${c.company_name}? This cannot be undone.`)) {
                            deleteClient.mutate(c.id);
                          }
                        }}
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>

      {/* Add dialog */}
      <Dialog open={addOpen} onOpenChange={setAddOpen}>
        <DialogContent className="sm:max-w-[520px]">
          <DialogHeader>
            <DialogTitle>Add Client</DialogTitle>
          </DialogHeader>
          {FormFields}
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddOpen(false)}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={isSaving}>
              {isSaving ? "Saving..." : "Add Client"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Edit dialog */}
      <Dialog open={!!editClient} onOpenChange={(o) => { if (!o) setEditClient(null); }}>
        <DialogContent className="sm:max-w-[520px]">
          <DialogHeader>
            <DialogTitle>Edit Client</DialogTitle>
          </DialogHeader>
          {FormFields}
          <DialogFooter>
            <Button variant="outline" onClick={() => setEditClient(null)}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={isSaving}>
              {isSaving ? "Saving..." : "Save Changes"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Communication log panel */}
      {commClientId && commClient && user && (
        <CommLogPanel
          clientId={commClientId}
          clientName={commClient.company_name}
          teamId={teamId}
          userId={user.id}
          onClose={() => setCommClientId(null)}
        />
      )}
    </div>
  );
}

// ─── Mandates Tab ─────────────────────────────────────────────────────────────

function MandatesTab({ teamId }: { teamId: string }) {
  const { mandates, isLoading, createMandate, updateMandate } = useAgencyMandates(teamId);
  const { clients } = useAgencyClients(teamId);

  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [addOpen, setAddOpen] = useState(false);

  const [form, setForm] = useState({
    client_id: "",
    job_title: "",
    description: "",
    priority: "medium" as AgencyMandate["priority"],
    status: "open" as AgencyMandate["status"],
    fee_type: "percentage" as AgencyMandate["fee_type"],
    fee_amount: "",
    deadline: "",
  });

  function resetForm() {
    setForm({ client_id: "", job_title: "", description: "", priority: "medium", status: "open", fee_type: "percentage", fee_amount: "", deadline: "" });
  }

  async function handleSubmit() {
    if (!form.client_id) { toast.error("Select a client"); return; }
    if (!form.job_title.trim()) { toast.error("Job title is required"); return; }
    await createMandate.mutateAsync({
      client_id: form.client_id,
      job_title: form.job_title.trim(),
      description: form.description.trim() || null,
      priority: form.priority,
      status: form.status,
      fee_type: form.fee_type,
      fee_amount: form.fee_amount ? parseFloat(form.fee_amount) : null,
      deadline: form.deadline || null,
    });
    setAddOpen(false);
    resetForm();
  }

  const filtered = useMemo(() => {
    return statusFilter === "all" ? mandates : mandates.filter((m) => m.status === statusFilter);
  }, [mandates, statusFilter]);

  // Counts for urgent signal
  const urgentCount = mandates.filter((m) => {
    if (m.status === "cancelled" || m.status === "filled") return false;
    if (!m.deadline) return false;
    return differenceInDays(parseISO(m.deadline), new Date()) <= 3;
  }).length;

  return (
    <div className="space-y-5">
      {urgentCount > 0 && (
        <div className="flex items-center gap-2 rounded-lg border border-amber-200 bg-amber-50 dark:border-amber-800 dark:bg-amber-900/20 px-4 py-2.5">
          <AlertTriangle className="h-4 w-4 text-amber-600 dark:text-amber-400 shrink-0" />
          <p className="text-sm text-amber-700 dark:text-amber-300 font-medium">
            {urgentCount} mandate{urgentCount > 1 ? "s" : ""} due within 3 days
          </p>
        </div>
      )}

      <div className="flex flex-col sm:flex-row gap-2">
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-full sm:w-[160px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Statuses</SelectItem>
            <SelectItem value="open">Open</SelectItem>
            <SelectItem value="in_progress">In Progress</SelectItem>
            <SelectItem value="filled">Filled</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
        <div className="flex-1" />
        <Button onClick={() => { resetForm(); setAddOpen(true); }} className="shrink-0 gap-1.5">
          <Plus className="h-4 w-4" />
          Add Mandate
        </Button>
      </div>

      <Card className="border border-border/60 shadow-sm">
        <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead>Job Title</TableHead>
              <TableHead>Client</TableHead>
              <TableHead>Priority</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Fee</TableHead>
              <TableHead>Deadline</TableHead>
              <TableHead>Created</TableHead>
              <TableHead className="w-[60px]"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton cols={8} />
            ) : filtered.length === 0 ? (
              <EmptyRow cols={8} message={mandates.length === 0 ? "No mandates yet. Add your first mandate." : "No mandates match the filter."} />
            ) : (
              filtered.map((m) => {
                const isUrgent =
                  m.deadline &&
                  m.status !== "cancelled" &&
                  m.status !== "filled" &&
                  differenceInDays(parseISO(m.deadline), new Date()) <= 3;

                return (
                  <TableRow
                    key={m.id}
                    className={`hover:bg-muted/30 transition-colors ${isUrgent ? "bg-amber-50/50 dark:bg-amber-900/10" : ""}`}
                  >
                    <TableCell className="font-medium text-sm">{m.job_title}</TableCell>
                    <TableCell className="text-sm text-muted-foreground">{m.client_name ?? "—"}</TableCell>
                    <TableCell><StatusBadge status={m.priority} /></TableCell>
                    <TableCell>
                      <Select
                        value={m.status}
                        onValueChange={(v) =>
                          updateMandate.mutate({ id: m.id, status: v as AgencyMandate["status"] })
                        }
                      >
                        <SelectTrigger className="h-7 w-[110px] text-xs border-none shadow-none px-2">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="open">Open</SelectItem>
                          <SelectItem value="in_progress">In Progress</SelectItem>
                          <SelectItem value="filled">Filled</SelectItem>
                          <SelectItem value="cancelled">Cancelled</SelectItem>
                        </SelectContent>
                      </Select>
                    </TableCell>
                    <TableCell className="text-sm">
                      {m.fee_amount != null
                        ? m.fee_type === "percentage"
                          ? `${m.fee_amount}%`
                          : fmtCurrency(m.fee_amount)
                        : "—"}
                    </TableCell>
                    <TableCell>
                      <DeadlineBadge deadline={m.deadline} />
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground">{fmtDate(m.created_at)}</TableCell>
                    <TableCell />
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </Card>

      <Dialog open={addOpen} onOpenChange={setAddOpen}>
        <DialogContent className="sm:max-w-[520px]">
          <DialogHeader>
            <DialogTitle>Add Mandate</DialogTitle>
          </DialogHeader>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Client *</Label>
              <Select value={form.client_id} onValueChange={(v) => setForm((f) => ({ ...f, client_id: v }))}>
                <SelectTrigger>
                  <SelectValue placeholder="Select client..." />
                </SelectTrigger>
                <SelectContent>
                  {clients.map((c) => (
                    <SelectItem key={c.id} value={c.id}>{c.company_name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Job Title *</Label>
              <Input
                value={form.job_title}
                onChange={(e) => setForm((f) => ({ ...f, job_title: e.target.value }))}
                placeholder="Senior Software Engineer"
              />
            </div>
            <div className="space-y-1.5">
              <Label>Priority</Label>
              <Select value={form.priority} onValueChange={(v) => setForm((f) => ({ ...f, priority: v as AgencyMandate["priority"] }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="low">Low</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Fee Type</Label>
              <Select value={form.fee_type} onValueChange={(v) => setForm((f) => ({ ...f, fee_type: v as AgencyMandate["fee_type"] }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="percentage">Percentage</SelectItem>
                  <SelectItem value="flat">Flat Fee</SelectItem>
                  <SelectItem value="retainer">Retainer</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Fee Amount</Label>
              <Input
                type="number"
                value={form.fee_amount}
                onChange={(e) => setForm((f) => ({ ...f, fee_amount: e.target.value }))}
                placeholder={form.fee_type === "percentage" ? "15" : "5000"}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Deadline</Label>
              <Input
                type="date"
                value={form.deadline}
                onChange={(e) => setForm((f) => ({ ...f, deadline: e.target.value }))}
              />
            </div>
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Description</Label>
              <Textarea
                value={form.description}
                onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))}
                rows={3}
                placeholder="Role requirements, responsibilities..."
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddOpen(false)}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={createMandate.isPending}>
              {createMandate.isPending ? "Creating..." : "Create Mandate"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ─── Placements Tab ───────────────────────────────────────────────────────────

function PlacementsTab({ teamId }: { teamId: string }) {
  const { placements, isLoading, createPlacement, updatePlacement } = useAgencyPlacements(teamId);
  const { mandates } = useAgencyMandates(teamId);

  const [addOpen, setAddOpen] = useState(false);
  const [form, setForm] = useState({
    mandate_id: "",
    client_id: "",
    candidate_name: "",
    candidate_email: "",
    salary: "",
    fee_amount: "",
    start_date: "",
    guarantee_days: "",
    status: "offered" as AgencyPlacement["status"],
  });

  function resetForm() {
    setForm({ mandate_id: "", client_id: "", candidate_name: "", candidate_email: "", salary: "", fee_amount: "", start_date: "", guarantee_days: "", status: "offered" });
  }

  function onMandateChange(mandateId: string) {
    const mandate = mandates.find((m) => m.id === mandateId);
    setForm((f) => ({
      ...f,
      mandate_id: mandateId,
      client_id: mandate?.client_id ?? f.client_id,
    }));
  }

  async function handleSubmit() {
    if (!form.mandate_id) { toast.error("Select a mandate"); return; }
    if (!form.candidate_name.trim()) { toast.error("Candidate name is required"); return; }
    const guarDays = form.guarantee_days ? parseInt(form.guarantee_days) : null;
    const startDate = form.start_date || null;
    const guarExpires = guarDays && startDate
      ? format(addDays(parseISO(startDate), guarDays), "yyyy-MM-dd")
      : null;

    await createPlacement.mutateAsync({
      mandate_id: form.mandate_id,
      client_id: form.client_id,
      candidate_name: form.candidate_name.trim(),
      candidate_email: form.candidate_email.trim() || null,
      salary: form.salary ? parseFloat(form.salary) : null,
      fee_amount: form.fee_amount ? parseFloat(form.fee_amount) : null,
      start_date: startDate,
      guarantee_days: guarDays,
      guarantee_expires_at: guarExpires,
      status: form.status,
    });
    setAddOpen(false);
    resetForm();
  }

  // Guarantee alert: placements in guarantee period expiring soon
  const expiringGuarantees = placements.filter((p) => {
    if (p.status !== "guarantee" || !p.guarantee_expires_at) return false;
    const days = differenceInDays(parseISO(p.guarantee_expires_at), new Date());
    return days >= 0 && days <= 7;
  });

  return (
    <div className="space-y-5">
      {expiringGuarantees.length > 0 && (
        <div className="flex items-center gap-2 rounded-lg border border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-900/20 px-4 py-2.5">
          <AlertTriangle className="h-4 w-4 text-red-600 dark:text-red-400 shrink-0" />
          <p className="text-sm text-red-700 dark:text-red-300 font-medium">
            {expiringGuarantees.length} guarantee{expiringGuarantees.length > 1 ? "s" : ""} expiring within 7 days
          </p>
        </div>
      )}

      <div className="flex justify-end">
        <Button onClick={() => { resetForm(); setAddOpen(true); }} className="gap-1.5">
          <Plus className="h-4 w-4" />
          Record Placement
        </Button>
      </div>

      <Card className="border border-border/60 shadow-sm">
        <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead>Candidate</TableHead>
              <TableHead>Client</TableHead>
              <TableHead>Mandate</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Start Date</TableHead>
              <TableHead>Salary</TableHead>
              <TableHead>Fee</TableHead>
              <TableHead>Guarantee</TableHead>
              <TableHead className="w-[60px]"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton cols={9} />
            ) : placements.length === 0 ? (
              <EmptyRow cols={9} message="No placements recorded yet." />
            ) : (
              placements.map((p) => (
                <TableRow key={p.id} className="hover:bg-muted/30 transition-colors">
                  <TableCell>
                    <div>
                      <p className="font-medium text-sm">{p.candidate_name}</p>
                      {p.candidate_email && (
                        <p className="text-xs text-muted-foreground">{p.candidate_email}</p>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">{p.client_name ?? "—"}</TableCell>
                  <TableCell className="text-sm text-muted-foreground">{p.mandate_title ?? "—"}</TableCell>
                  <TableCell>
                    <Select
                      value={p.status}
                      onValueChange={(v) =>
                        updatePlacement.mutate({ id: p.id, status: v as AgencyPlacement["status"] })
                      }
                    >
                      <SelectTrigger className="h-7 w-[115px] text-xs border-none shadow-none px-2">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="offered">Offered</SelectItem>
                        <SelectItem value="accepted">Accepted</SelectItem>
                        <SelectItem value="started">Started</SelectItem>
                        <SelectItem value="guarantee">In Guarantee</SelectItem>
                        <SelectItem value="completed">Completed</SelectItem>
                        <SelectItem value="fallen_off">Fallen Off</SelectItem>
                      </SelectContent>
                    </Select>
                  </TableCell>
                  <TableCell className="text-sm">{fmtDate(p.start_date)}</TableCell>
                  <TableCell className="text-sm">{fmtCurrency(p.salary)}</TableCell>
                  <TableCell className="text-sm">{fmtCurrency(p.fee_amount)}</TableCell>
                  <TableCell>
                    <GuarantyProgress
                      startDate={p.start_date}
                      guaranteeDays={p.guarantee_days}
                      expiresAt={p.guarantee_expires_at}
                    />
                  </TableCell>
                  <TableCell />
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>

      <Dialog open={addOpen} onOpenChange={setAddOpen}>
        <DialogContent className="sm:max-w-[540px]">
          <DialogHeader>
            <DialogTitle>Record Placement</DialogTitle>
          </DialogHeader>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Mandate *</Label>
              <Select value={form.mandate_id} onValueChange={onMandateChange}>
                <SelectTrigger>
                  <SelectValue placeholder="Select mandate..." />
                </SelectTrigger>
                <SelectContent>
                  {mandates.filter((m) => m.status !== "cancelled").map((m) => (
                    <SelectItem key={m.id} value={m.id}>
                      {m.job_title} — {m.client_name ?? "Unknown"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Candidate Name *</Label>
              <Input
                value={form.candidate_name}
                onChange={(e) => setForm((f) => ({ ...f, candidate_name: e.target.value }))}
                placeholder="Jane Smith"
              />
            </div>
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Candidate Email</Label>
              <Input
                type="email"
                value={form.candidate_email}
                onChange={(e) => setForm((f) => ({ ...f, candidate_email: e.target.value }))}
                placeholder="jane@example.com"
              />
            </div>
            <div className="space-y-1.5">
              <Label>Start Date</Label>
              <Input
                type="date"
                value={form.start_date}
                onChange={(e) => setForm((f) => ({ ...f, start_date: e.target.value }))}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Guarantee Days</Label>
              <Input
                type="number"
                value={form.guarantee_days}
                onChange={(e) => setForm((f) => ({ ...f, guarantee_days: e.target.value }))}
                placeholder="90"
                min={0}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Annual Salary</Label>
              <Input
                type="number"
                value={form.salary}
                onChange={(e) => setForm((f) => ({ ...f, salary: e.target.value }))}
                placeholder="80000"
              />
            </div>
            <div className="space-y-1.5">
              <Label>Placement Fee</Label>
              <Input
                type="number"
                value={form.fee_amount}
                onChange={(e) => setForm((f) => ({ ...f, fee_amount: e.target.value }))}
                placeholder="12000"
              />
            </div>
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Status</Label>
              <Select value={form.status} onValueChange={(v) => setForm((f) => ({ ...f, status: v as AgencyPlacement["status"] }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="offered">Offered</SelectItem>
                  <SelectItem value="accepted">Accepted</SelectItem>
                  <SelectItem value="started">Started</SelectItem>
                  <SelectItem value="guarantee">In Guarantee</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                  <SelectItem value="fallen_off">Fallen Off</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddOpen(false)}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={createPlacement.isPending}>
              {createPlacement.isPending ? "Saving..." : "Record Placement"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ─── Invoicing Tab ────────────────────────────────────────────────────────────

function InvoicingTab({ teamId }: { teamId: string }) {
  const { invoices, isLoading, createInvoice, updateInvoice } = useAgencyInvoices(teamId);
  const { clients } = useAgencyClients(teamId);
  const { placements } = useAgencyPlacements(teamId);

  const [addOpen, setAddOpen] = useState(false);
  const [form, setForm] = useState({
    client_id: "",
    placement_id: "",
    invoice_number: `INV-${Date.now().toString().slice(-6)}`,
    amount: "",
    currency: "USD",
    due_date: "",
    status: "draft" as AgencyInvoice["status"],
  });

  function resetForm() {
    setForm({
      client_id: "",
      placement_id: "",
      invoice_number: `INV-${Date.now().toString().slice(-6)}`,
      amount: "",
      currency: "USD",
      due_date: "",
      status: "draft",
    });
  }

  async function handleSubmit() {
    if (!form.client_id) { toast.error("Select a client"); return; }
    if (!form.amount) { toast.error("Amount is required"); return; }
    await createInvoice.mutateAsync({
      client_id: form.client_id,
      placement_id: form.placement_id || null,
      invoice_number: form.invoice_number,
      amount: parseFloat(form.amount),
      currency: form.currency,
      due_date: form.due_date || null,
      status: form.status,
      paid_at: null,
    });
    setAddOpen(false);
    resetForm();
  }

  function handleMarkPaid(invoice: AgencyInvoice) {
    updateInvoice.mutate({
      id: invoice.id,
      status: "paid",
      paid_at: new Date().toISOString(),
    });
  }

  function exportCSV() {
    const rows = [
      ["Invoice #", "Client", "Amount", "Currency", "Status", "Due Date", "Paid Date"],
      ...invoices.map((inv) => [
        inv.invoice_number,
        inv.client_name ?? "",
        String(inv.amount),
        inv.currency,
        inv.status,
        inv.due_date ?? "",
        inv.paid_at ? format(parseISO(inv.paid_at), "yyyy-MM-dd") : "",
      ]),
    ];
    const csv = rows.map((r) => r.map((c) => `"${c}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `invoices-${format(new Date(), "yyyy-MM-dd")}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

  const totalInvoiced = invoices.reduce((s, i) => s + i.amount, 0);
  const totalPaid = invoices.filter((i) => i.status === "paid").reduce((s, i) => s + i.amount, 0);
  const totalOverdue = invoices.filter((i) => i.status === "overdue").reduce((s, i) => s + i.amount, 0);

  const overdueInvoices = invoices.filter((i) => i.status === "overdue");

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
        <SummaryCard label="Total Invoiced" value={fmtCurrency(totalInvoiced)} icon={Receipt} />
        <SummaryCard label="Paid" value={fmtCurrency(totalPaid)} icon={CheckCircle2} accent="emerald" />
        <SummaryCard label="Overdue" value={fmtCurrency(totalOverdue)} icon={AlertTriangle} accent={totalOverdue > 0 ? "red" : undefined} />
      </div>

      {overdueInvoices.length > 0 && (
        <div className="space-y-1.5">
          <p className="text-xs font-medium text-red-600 dark:text-red-400 flex items-center gap-1.5">
            <AlertTriangle className="h-3.5 w-3.5" />
            Overdue invoices require attention
          </p>
        </div>
      )}

      <div className="flex justify-end gap-2">
        <Button variant="outline" className="gap-1.5" onClick={exportCSV}>
          <Download className="h-4 w-4" />
          Export CSV
        </Button>
        <Button onClick={() => { resetForm(); setAddOpen(true); }} className="gap-1.5">
          <Plus className="h-4 w-4" />
          New Invoice
        </Button>
      </div>

      <Card className="border border-border/60 shadow-sm">
        <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead>Invoice #</TableHead>
              <TableHead>Client</TableHead>
              <TableHead>Amount</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Due Date</TableHead>
              <TableHead>Paid Date</TableHead>
              <TableHead className="w-[120px]"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton cols={7} />
            ) : invoices.length === 0 ? (
              <EmptyRow cols={7} message="No invoices yet." />
            ) : (
              invoices.map((inv) => {
                const isOverdue = inv.status === "overdue";
                return (
                  <TableRow
                    key={inv.id}
                    className={`hover:bg-muted/30 transition-colors ${isOverdue ? "bg-red-50/60 dark:bg-red-900/10" : ""}`}
                  >
                    <TableCell className="font-mono text-sm">{inv.invoice_number}</TableCell>
                    <TableCell className="text-sm">{inv.client_name ?? "—"}</TableCell>
                    <TableCell className={`text-sm font-medium ${isOverdue ? "text-red-600 dark:text-red-400" : ""}`}>
                      {fmtCurrency(inv.amount, inv.currency)}
                    </TableCell>
                    <TableCell><StatusBadge status={inv.status} /></TableCell>
                    <TableCell className={`text-sm ${isOverdue ? "text-red-600 dark:text-red-400 font-medium" : "text-muted-foreground"}`}>
                      {fmtDate(inv.due_date)}
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {inv.paid_at ? fmtDate(inv.paid_at) : "—"}
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1">
                        {inv.status !== "paid" && (
                          <Button
                            variant="outline"
                            size="sm"
                            className="h-7 text-xs"
                            onClick={() => handleMarkPaid(inv)}
                            disabled={updateInvoice.isPending}
                          >
                            Mark Paid
                          </Button>
                        )}
                        {inv.status === "sent" && (
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-7 text-xs"
                            onClick={() => toast.info("Send reminder — coming soon")}
                          >
                            Remind
                          </Button>
                        )}
                      </div>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </Card>

      <Dialog open={addOpen} onOpenChange={setAddOpen}>
        <DialogContent className="sm:max-w-[480px]">
          <DialogHeader>
            <DialogTitle>Generate Invoice</DialogTitle>
          </DialogHeader>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Client *</Label>
              <Select value={form.client_id} onValueChange={(v) => setForm((f) => ({ ...f, client_id: v }))}>
                <SelectTrigger><SelectValue placeholder="Select client..." /></SelectTrigger>
                <SelectContent>
                  {clients.map((c) => (
                    <SelectItem key={c.id} value={c.id}>{c.company_name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Link to Placement (optional)</Label>
              <Select value={form.placement_id} onValueChange={(v) => setForm((f) => ({ ...f, placement_id: v }))}>
                <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {placements
                    .filter((p) => !form.client_id || p.client_id === form.client_id)
                    .map((p) => (
                      <SelectItem key={p.id} value={p.id}>{p.candidate_name}</SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Invoice Number</Label>
              <Input
                value={form.invoice_number}
                onChange={(e) => setForm((f) => ({ ...f, invoice_number: e.target.value }))}
              />
            </div>
            <div className="space-y-1.5">
              <Label>Currency</Label>
              <Select value={form.currency} onValueChange={(v) => setForm((f) => ({ ...f, currency: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="USD">USD</SelectItem>
                  <SelectItem value="GBP">GBP</SelectItem>
                  <SelectItem value="EUR">EUR</SelectItem>
                  <SelectItem value="AUD">AUD</SelectItem>
                  <SelectItem value="CAD">CAD</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Amount *</Label>
              <Input
                type="number"
                value={form.amount}
                onChange={(e) => setForm((f) => ({ ...f, amount: e.target.value }))}
                placeholder="10000"
              />
            </div>
            <div className="space-y-1.5">
              <Label>Due Date</Label>
              <Input
                type="date"
                value={form.due_date}
                onChange={(e) => setForm((f) => ({ ...f, due_date: e.target.value }))}
              />
            </div>
            <div className="sm:col-span-2 space-y-1.5">
              <Label>Status</Label>
              <Select value={form.status} onValueChange={(v) => setForm((f) => ({ ...f, status: v as AgencyInvoice["status"] }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="sent">Sent</SelectItem>
                  <SelectItem value="paid">Paid</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddOpen(false)}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={createInvoice.isPending}>
              {createInvoice.isPending ? "Creating..." : "Create Invoice"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// ─── Commission Tab ───────────────────────────────────────────────────────────

function CommissionTab({ teamId }: { teamId: string }) {
  const { commissions, totals, isLoading } = useAgencyCommissions(teamId);
  const [periodFilter, setPeriodFilter] = useState<string>("all");

  const periodOptions = useMemo(() => {
    const opts: { value: string; label: string }[] = [{ value: "all", label: "All Periods" }];
    for (let i = 0; i < 6; i++) {
      const d = new Date();
      d.setMonth(d.getMonth() - i);
      const val = format(d, "yyyy-MM");
      opts.push({ value: val, label: format(d, "MMMM yyyy") });
    }
    return opts;
  }, []);

  const filtered = useMemo(() => {
    if (periodFilter === "all") return commissions;
    return commissions.filter((c) => (c.period ?? "").startsWith(periodFilter));
  }, [commissions, periodFilter]);

  // Status accent map for commission rows
  function commStatusAccent(status: string): string {
    if (status === "paid") return "text-emerald-600 dark:text-emerald-400";
    if (status === "approved") return "text-blue-600 dark:text-blue-400";
    if (status === "pending") return "text-amber-600 dark:text-amber-400";
    return "text-muted-foreground";
  }

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
        <SummaryCard label="Total Earned" value={fmtCurrency(totals.earned)} icon={TrendingUp} />
        <SummaryCard label="Pending" value={fmtCurrency(totals.pending)} icon={Clock} accent={totals.pending > 0 ? "amber" : undefined} />
        <SummaryCard label="Paid Out" value={fmtCurrency(totals.paid)} icon={CheckCircle2} accent="emerald" />
      </div>

      <div className="flex justify-end">
        <Select value={periodFilter} onValueChange={setPeriodFilter}>
          <SelectTrigger className="w-[180px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {periodOptions.map((o) => (
              <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <Card className="border border-border/60 shadow-sm">
        <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead>Candidate</TableHead>
              <TableHead>Commission %</TableHead>
              <TableHead>Amount</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Period</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton cols={5} />
            ) : filtered.length === 0 ? (
              <EmptyRow cols={5} message="No commission records found." />
            ) : (
              filtered.map((c) => (
                <TableRow key={c.id} className="hover:bg-muted/30 transition-colors">
                  <TableCell className="font-medium text-sm">{c.candidate_name ?? "—"}</TableCell>
                  <TableCell className="text-sm">{c.percentage}%</TableCell>
                  <TableCell className={`text-sm font-medium ${commStatusAccent(c.status)}`}>
                    {fmtCurrency(c.amount)}
                  </TableCell>
                  <TableCell><StatusBadge status={c.status} /></TableCell>
                  <TableCell className="text-sm text-muted-foreground">{c.period ?? "—"}</TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>
    </div>
  );
}

// ─── Analytics Tab ────────────────────────────────────────────────────────────

function AnalyticsTab({ teamId }: { teamId: string }) {
  const { clients } = useAgencyClients(teamId);
  const { mandates } = useAgencyMandates(teamId);
  const { placements } = useAgencyPlacements(teamId);
  const { invoices } = useAgencyInvoices(teamId);
  const { totals: commTotals } = useAgencyCommissions(teamId);

  // Computed metrics
  const activeClients = clients.filter((c) => c.status === "active").length;
  const openMandates = mandates.filter((m) => m.status === "open" || m.status === "in_progress").length;
  const filledMandates = mandates.filter((m) => m.status === "filled").length;
  const fillRate = mandates.length > 0 ? Math.round((filledMandates / mandates.length) * 100) : 0;

  const completedPlacements = placements.filter((p) => p.status === "completed" || p.status === "started" || p.status === "guarantee").length;
  const fallenOff = placements.filter((p) => p.status === "fallen_off").length;
  const retentionRate = placements.length > 0 ? Math.round(((placements.length - fallenOff) / placements.length) * 100) : 0;

  const totalRevenue = invoices.filter((i) => i.status === "paid").reduce((s, i) => s + i.amount, 0);
  const avgFee = completedPlacements > 0
    ? Math.round(placements.filter((p) => p.fee_amount != null).reduce((s, p) => s + (p.fee_amount ?? 0), 0) / (placements.filter((p) => p.fee_amount != null).length || 1))
    : 0;

  // Mandate status breakdown
  const mandateBreakdown = [
    { label: "Open", count: mandates.filter((m) => m.status === "open").length, color: "bg-blue-500" },
    { label: "In Progress", count: mandates.filter((m) => m.status === "in_progress").length, color: "bg-amber-500" },
    { label: "Filled", count: mandates.filter((m) => m.status === "filled").length, color: "bg-emerald-500" },
    { label: "Cancelled", count: mandates.filter((m) => m.status === "cancelled").length, color: "bg-gray-400" },
  ];

  // Placement status breakdown
  const placementBreakdown = [
    { label: "Active (started/guarantee)", count: placements.filter((p) => p.status === "started" || p.status === "guarantee").length, color: "bg-emerald-500" },
    { label: "Completed", count: placements.filter((p) => p.status === "completed").length, color: "bg-blue-500" },
    { label: "Fallen Off", count: fallenOff, color: "bg-red-500" },
    { label: "Offered/Accepted", count: placements.filter((p) => p.status === "offered" || p.status === "accepted").length, color: "bg-violet-500" },
  ];

  return (
    <div className="space-y-6">
      {/* KPI row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <SummaryCard label="Active Clients" value={String(activeClients)} icon={Users} accent="emerald" />
        <SummaryCard label="Open Mandates" value={String(openMandates)} icon={FileText} />
        <SummaryCard label="Fill Rate" value={`${fillRate}%`} icon={Award} accent={fillRate >= 70 ? "emerald" : fillRate >= 40 ? "amber" : "red"} sub={`${filledMandates} of ${mandates.length} mandates`} />
        <SummaryCard label="Total Revenue" value={fmtCurrency(totalRevenue)} icon={TrendingUp} accent="emerald" />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {/* Mandate breakdown */}
        <Card className="border border-border/60 shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-semibold">Mandates by Status</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {mandates.length === 0 ? (
              <p className="text-sm text-muted-foreground">No mandates yet.</p>
            ) : (
              mandateBreakdown.map((row) => (
                <div key={row.label} className="space-y-1">
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-muted-foreground">{row.label}</span>
                    <span className="font-medium">{row.count}</span>
                  </div>
                  <div className="h-1.5 rounded-full bg-muted overflow-hidden">
                    <div
                      className={`h-full rounded-full ${row.color}`}
                      style={{ width: `${mandates.length > 0 ? (row.count / mandates.length) * 100 : 0}%` }}
                    />
                  </div>
                </div>
              ))
            )}
          </CardContent>
        </Card>

        {/* Placement breakdown */}
        <Card className="border border-border/60 shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-semibold">Placements by Status</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {placements.length === 0 ? (
              <p className="text-sm text-muted-foreground">No placements yet.</p>
            ) : (
              placementBreakdown.map((row) => (
                <div key={row.label} className="space-y-1">
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-muted-foreground">{row.label}</span>
                    <span className="font-medium">{row.count}</span>
                  </div>
                  <div className="h-1.5 rounded-full bg-muted overflow-hidden">
                    <div
                      className={`h-full rounded-full ${row.color}`}
                      style={{ width: `${placements.length > 0 ? (row.count / placements.length) * 100 : 0}%` }}
                    />
                  </div>
                </div>
              ))
            )}
          </CardContent>
        </Card>
      </div>

      {/* Summary metrics */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <SummaryCard
          label="Retention Rate"
          value={`${retentionRate}%`}
          icon={CheckCircle2}
          accent={retentionRate >= 80 ? "emerald" : retentionRate >= 60 ? "amber" : "red"}
          sub={`${fallenOff} fallen off`}
        />
        <SummaryCard
          label="Avg Placement Fee"
          value={fmtCurrency(avgFee)}
          icon={DollarSign}
        />
        <SummaryCard
          label="Commission Earned"
          value={fmtCurrency(commTotals.earned)}
          icon={TrendingUp}
        />
        <SummaryCard
          label="Commission Pending"
          value={fmtCurrency(commTotals.pending)}
          icon={Clock}
          accent={commTotals.pending > 0 ? "amber" : undefined}
        />
      </div>
    </div>
  );
}

